def count_ones(n):
    """
    This function counts the number of ones in the binary representation of a number.
    """
    count = 0
    while n > 0:
        count += n % 2
        n //= 2
    return count

def sort_by_ones(arr):
    """
    This function sorts an array of non-negative integers based on the number of ones in their binary representation.
    """
    return sorted(arr, key=count_ones)

