def remove_char_at(str, n):
    """Create a copy of the string and remove the character at position n
    Args:
        str (str): The string to be modified
        n (int): The index of the character to be removed
    Returns:
        str: The modified string
    """
    if n < 0:
        return str
    return str[:n] + str[n+1:]
